import{_ as o,o as a,c as d,a1 as t}from"./chunks/framework.DceXOx8u.js";const h=JSON.parse('{"title":"Actualizar a estable: dependencias","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/migracion"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/migracion"}]]},"headers":[],"relativePath":"es/guide/migracion.md","filePath":"es/guide/migracion.md"}'),s={name:"es/guide/migracion.md"};function i(n,e,r,c,l,p){return a(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="actualizar-a-estable-dependencias" tabindex="-1">Actualizar a estable: dependencias <a class="header-anchor" href="#actualizar-a-estable-dependencias" aria-label="Permalink to &quot;Actualizar a estable: dependencias&quot;">​</a></h1><p>Paso 2 del <a href="./migracion-estable#checklist-de-actualizacion">checklist de actualización</a>. La línea estable pone al día las dependencias de los paquetes públicos y termina el cambio de nombre <code>botwa</code> → <code>botmesh</code>. Cada sección dice a quién afecta y qué hacer.</p><table tabindex="0"><thead><tr><th>Cambio</th><th>A quién afecta</th><th>Qué hacer</th></tr></thead><tbody><tr><td><a href="#nombres-de-metricas-de-prometheus-prefijo-botmesh">Métricas <code>botmesh_</code></a></td><td>Dashboards y alertas sobre <code>botwa_*</code></td><td>Renombra las consultas, o pasa <code>{ prefix: &#39;botwa_&#39; }</code></td></tr><tr><td><a href="#variables-de-entorno">Variables de entorno</a></td><td>Scripts que definen <code>BOTWA_*</code></td><td>Renómbralas (los nombres viejos se siguen leyendo)</td></tr><tr><td><a href="#botmesh-redis-store-redis-es-una-dependencia-peer"><code>redis</code> es peer</a></td><td>Quien usa <code>@botmesh/redis-store</code></td><td>Nada, salvo si tipaste clientes con <code>NativeRedisClient</code></td></tr><tr><td><a href="#botmesh-baileys-ffmpeg-ya-no-viene-incluido">ffmpeg ya no viene incluido</a></td><td>Bots de Baileys que envían notas de voz</td><td>Instala ffmpeg, o <code>ffmpeg-static</code></td></tr><tr><td><a href="#providers-de-meta-graph-api-v26-0">Graph API v26.0</a></td><td>Cloud API, Messenger, Instagram</td><td>Nada, o fija <code>apiVersion</code></td></tr><tr><td><a href="#botmesh-ai-sdk-y-modelos-por-defecto">SDK y modelos de IA</a></td><td>Bots de Gemini; bots sin <code>model</code> explícito</td><td><code>pnpm add @google/genai</code>; fija <code>model</code></td></tr><tr><td><a href="#nombres-que-se-mantienen">Nombres que se mantienen</a></td><td>Todos</td><td>Nada: las claves y prefijos <code>botwa</code> guardados siguen funcionando</td></tr></tbody></table><h2 id="nombres-de-metricas-de-prometheus-prefijo-botmesh" tabindex="-1">Nombres de métricas de Prometheus: prefijo <code>botmesh_</code> <a class="header-anchor" href="#nombres-de-metricas-de-prometheus-prefijo-botmesh" aria-label="Permalink to &quot;Nombres de métricas de Prometheus: prefijo `botmesh_`&quot;">​</a></h2><p><code>toPrometheus(bot.metrics())</code> (<code>@botmesh/core</code>) nombra ahora cada familia <code>botmesh_*</code> en lugar de <code>botwa_*</code>, por ejemplo <code>botmesh_messages_in_total</code>. Los paneles y alertas que consultan los nombres anteriores siguen funcionando si pasas el prefijo antiguo:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toPrometheus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bot.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">metrics</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), { prefix: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;botwa_&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>El puente de OpenTelemetry (<code>@botmesh/otel</code>) pasó de <code>botwa.*</code> a <code>botmesh.*</code> de la misma forma (<code>otelMetricsPlugin({ prefix: &#39;botwa&#39; })</code> conserva los nombres anteriores), y el control plane (<code>@botmesh/manager</code>) sirve ahora <code>botmesh_manager_bots_registered</code> y <code>botmesh_manager_bots_running</code>.</p><h2 id="variables-de-entorno" tabindex="-1">Variables de entorno <a class="header-anchor" href="#variables-de-entorno" aria-label="Permalink to &quot;Variables de entorno&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nombre nuevo</th><th>Nombre anterior (se sigue leyendo)</th><th>Dónde</th></tr></thead><tbody><tr><td><code>BOTMESH_DEV=1</code></td><td><code>BOT_WA_DEV=1</code> (se sigue definiendo)</td><td>la define <code>botmesh dev</code> para el código de tu bot</td></tr><tr><td><code>BOTMESH_MANAGER_LOG_LEVEL</code></td><td><code>BOTWA_MANAGER_LOG_LEVEL</code></td><td>logger por defecto de <code>BotManager</code></td></tr><tr><td><code>BOTMESH_DOCS_DIR</code></td><td><code>BOTWA_DOCS_DIR</code></td><td>árbol de documentación del servidor MCP</td></tr></tbody></table><p>La query de recarga en caliente de <code>botmesh dev</code> es ahora <code>?botmesh_v=&lt;n&gt;</code> (solo se ve en las trazas de pila).</p><h2 id="botmesh-redis-store-redis-es-una-dependencia-peer" tabindex="-1"><code>@botmesh/redis-store</code>: <code>redis</code> es una dependencia peer <a class="header-anchor" href="#botmesh-redis-store-redis-es-una-dependencia-peer" aria-label="Permalink to &quot;`@botmesh/redis-store`: `redis` es una dependencia peer&quot;">​</a></h2><p><code>redis</code> (node-redis) pasó de <code>dependencies</code> a <code>peerDependencies</code> con el rango <code>^4.7.0 || ^5.0.0 || ^6.0.0</code>. npm y pnpm instalan solos una dependencia peer que falta (node-redis 6), así que <code>pnpm add @botmesh/redis-store</code> sigue funcionando; si ya dependes de <code>redis</code>, el store usa tu versión.</p><ul><li>node-redis 5 y 6 quedan soportados, en un nodo y en Redis Cluster, con RESP2 o RESP3 (el valor por defecto de node-redis 6).</li><li><code>NativeRedisClient</code> y <code>NativeRedisClusterClient</code> son ahora interfaces estructurales pequeñas en lugar de <code>ReturnType&lt;typeof createClient&gt;</code>, de modo que el cliente de cualquier major soportada pasa el chequeo de tipos. Si los usabas para llamar comandos, usa el tipo de <code>redis</code> (<code>ReturnType&lt;typeof createClient&gt;</code>).</li></ul><h2 id="botmesh-baileys-ffmpeg-ya-no-viene-incluido" tabindex="-1"><code>@botmesh/baileys</code>: ffmpeg ya no viene incluido <a class="header-anchor" href="#botmesh-baileys-ffmpeg-ya-no-viene-incluido" aria-label="Permalink to &quot;`@botmesh/baileys`: ffmpeg ya no viene incluido&quot;">​</a></h2><p>El provider ya no depende de <code>fluent-ffmpeg</code> (obsoleto) ni de <code>@ffmpeg-installer/ffmpeg</code> (sin mantenimiento, con un ffmpeg antiguo). Las notas de voz se transcodifican ejecutando directamente un binario de ffmpeg, que se busca en este orden:</p><ol><li><code>FFMPEG_PATH</code>, si está definida;</li><li>la dependencia peer opcional <code>ffmpeg-static</code>, si está instalada y su binario se descargó (con pnpm, permite su script de build);</li><li><code>ffmpeg</code> en el <code>PATH</code> (<code>apt install ffmpeg</code>, <code>brew install ffmpeg</code>, <code>choco install ffmpeg</code>).</li></ol><p>Sin ninguno de ellos, una nota de voz se rechaza con un <code>UnsupportedContentError</code> que explica cómo instalar ffmpeg (si <code>ffmpeg-static</code> está instalado pero su binario nunca se descargó, el mensaje dice que permitas su script de build y lo reinstales). El texto, las imágenes y el resto no se ven afectados. La imagen Docker de un bot que envía notas de voz necesita ffmpeg (o <code>ffmpeg-static</code>).</p><p>Baileys sigue en <code>7.0.0-rc14</code>: todavía no existe una 7.x estable (ver el <a href="https://github.com/andresayac/botmesh/tree/main/packages/baileys-provider#requirements" target="_blank" rel="noreferrer">README del paquete</a> y su política de actualización de upstream).</p><h2 id="providers-de-meta-graph-api-v26-0" tabindex="-1">Providers de Meta: Graph API v26.0 <a class="header-anchor" href="#providers-de-meta-graph-api-v26-0" aria-label="Permalink to &quot;Providers de Meta: Graph API v26.0&quot;">​</a></h2><p><code>@botmesh/meta</code>, <code>@botmesh/messenger</code> y <code>@botmesh/instagram</code> llaman ahora por defecto a la Graph API <code>v26.0</code> (antes <code>v21.0</code>, que Meta retira el 21-01-2027). Los payloads de envío y de webhook que usan los providers no cambiaron entre esas versiones. Para quedarte en una versión, fíjala:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CloudAPIProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> apiVersion: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;v21.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>El estado <code>played</code> de WhatsApp (se escuchó una nota de voz) llega ahora como <code>status: &#39;read&#39;</code> con <code>platformData.played: true</code>; antes se descartaba.</p><h2 id="botmesh-ai-sdk-y-modelos-por-defecto" tabindex="-1"><code>@botmesh/ai</code>: SDK y modelos por defecto <a class="header-anchor" href="#botmesh-ai-sdk-y-modelos-por-defecto" aria-label="Permalink to &quot;`@botmesh/ai`: SDK y modelos por defecto&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cambio</th><th>Antes</th><th>Ahora</th></tr></thead><tbody><tr><td>SDK de Gemini</td><td><code>@google/generative-ai</code> (obsoleto)</td><td><code>@google/genai</code> <code>^2</code>; el SDK anterior se sigue usando, con un <code>DeprecationWarning</code>, si el nuevo no está instalado</td></tr><tr><td>Modelo por defecto de Anthropic</td><td><code>claude-opus-4-8</code></td><td><code>claude-opus-5-5</code></td></tr><tr><td>Modelo por defecto de Gemini</td><td><code>gemini-2.0-flash</code> (apagado por Google)</td><td><code>gemini-3.8-flash</code></td></tr><tr><td>Modelo del preset <code>grok</code></td><td><code>grok-2-latest</code></td><td><code>grok-4.7</code></td></tr><tr><td>Modelo del preset <code>glm</code></td><td><code>glm-4-plus</code></td><td><code>glm-5.3</code></td></tr></tbody></table><p>Para mover un bot de Gemini: <code>pnpm remove @google/generative-ai &amp;&amp; pnpm add @google/genai</code>. Nada más cambia en <code>aiPlugin</code>; <code>baseUrl</code> pasa a ser el <code>httpOptions.baseUrl</code> del SDK. Para Vertex AI, crea el cliente tú mismo con <code>fromGoogleGenAI</code> (ver <a href="/botmesh/es/guide/ai#gemini">Gemini</a>).</p><p>Los modelos por defecto no entran en semver: fija <code>model</code> si la elección te importa. Claude Opus 5.5 siempre piensa (<code>thinking: &#39;off&#39;</code> no reduce nada en él; usa <code>effort: &#39;low&#39;</code>) y su esfuerzo por defecto es <code>medium</code>.</p><h2 id="botmesh-hub-campo-botmesh-del-manifiesto" tabindex="-1"><code>@botmesh/hub</code>: campo <code>botmesh</code> del manifiesto <a class="header-anchor" href="#botmesh-hub-campo-botmesh-del-manifiesto" aria-label="Permalink to &quot;`@botmesh/hub`: campo `botmesh` del manifiesto&quot;">​</a></h2><p>Un manifiesto de plugin declara su rango de runtime en <code>botmesh</code> (<code>&quot;botmesh&quot;: &quot;^2.0.0&quot;</code>). Los manifiestos con el campo antiguo <code>botwa</code> se siguen aceptando, y la validación los devuelve con <code>botmesh</code>.</p><h2 id="eslint-plugin-botmesh-nombres-de-los-tipos" tabindex="-1"><code>eslint-plugin-botmesh</code>: nombres de los tipos <a class="header-anchor" href="#eslint-plugin-botmesh-nombres-de-los-tipos" aria-label="Permalink to &quot;`eslint-plugin-botmesh`: nombres de los tipos&quot;">​</a></h2><p>Los tipos exportados son <code>BotMeshConfigs</code> y <code>BotMeshPlugin</code>. Los antiguos <code>BotWaConfigs</code> y <code>BotWaPlugin</code> se mantienen como alias obsoletos de los mismos tipos, así que los imports existentes siguen compilando; renómbralos cuando te venga bien.</p><h2 id="nombres-que-se-mantienen" tabindex="-1">Nombres que se mantienen <a class="header-anchor" href="#nombres-que-se-mantienen" aria-label="Permalink to &quot;Nombres que se mantienen&quot;">​</a></h2><p>Algunos identificadores del nombre anterior del proyecto viven en datos ya guardados. Renombrarlos ocultaría datos que ya existen, así que son permanentes:</p><table tabindex="0"><thead><tr><th>Nombre</th><th>Dónde</th></tr></thead><tbody><tr><td>prefijo de claves <code>&#39;botwa&#39;</code></td><td><code>prefix</code> por defecto de <code>RedisStore</code>, <code>RedisCoordinator</code>, <code>RedisDurability</code>, <code>RedisScheduleStore</code> y <code>RedisLeaseProvider</code></td></tr><tr><td><code>$botwaMedia</code></td><td>marcador de media dentro de los registros del inbox durable</td></tr><tr><td><code>&#39;botwa:durable&#39;</code>, <code>botwa.inbound.*</code>, <code>botwa.outbox</code></td><td>canal, tipos de evento y sidecar de <code>@botmesh/events/durability</code></td></tr><tr><td>base de datos <code>botwa</code></td><td>base por defecto de <code>MongoStore</code> y de las cadenas de conexión de Postgres/MySQL</td></tr><tr><td><code>BOTWA_TEST_*</code></td><td>variables de los tests de integración del propio repositorio (ningún paquete publicado las lee)</td></tr></tbody></table><p>Pasa tu propio <code>prefix</code>, <code>dbName</code> o cadena de conexión para usar otros nombres en un despliegue nuevo.</p><h2 id="siguientes-pasos" tabindex="-1">Siguientes pasos <a class="header-anchor" href="#siguientes-pasos" aria-label="Permalink to &quot;Siguientes pasos&quot;">​</a></h2><ul><li><a href="./migracion-estable">Actualizar a estable: checklist y cambios de API</a></li><li><a href="./migracion-2">Actualizar a estable: cambios de comportamiento</a></li></ul>',36)])])}const u=o(s,[["render",i]]);export{h as __pageData,u as default};
